    function createPixiSmallExplosion(PIXI, meta, base) {
        const body = part(PIXI, "small-explosion");
        const light = shade(base, 0.34);
        const dark = shade(base, -0.16);
        for (let i = 0; i < 10; i += 1) {
            const angle = (i / 10) * Math.PI * 2;
            const reach = 46 + (i % 2) * 16;
            const spread = 0.16;
            addPoly(body, PIXI, i % 2 ? light : base, [
                Math.cos(angle - spread) * 20,
                Math.sin(angle - spread) * 20,
                Math.cos(angle) * reach,
                Math.sin(angle) * reach,
                Math.cos(angle + spread) * 20,
                Math.sin(angle + spread) * 20,
            ], 0.92);
        }
        addCircle(body, PIXI, dark, 0, 0, 26, 0.85);
        addCircle(body, PIXI, base, 0, 0, 18, 0.95);
        addCircle(body, PIXI, "#ffe7a6", 0, 0, 9, 0.95);
        return { body, profile: "small-explosion" };
    }
